import numpy as np

def solve():
    a = [1/i for i in range(1, 11)]
    b = [1/(i+1) for i in range(1, 11)]

    A = np.zeros((10, 10), dtype=float)
    for i in range(10):
        for j in range(10):
            if i!= j:
                A[i, j] = a[i] * b[j]
            else:
                A[i, j] = 1 + a[i] * b[j]

    return np.linalg.det(A)

print(solve())
